import json
for k,v in T.items(): assert len(v)==len(KEYS),(k,len(v),len(KEYS))
out={k:dict(zip(KEYS,v)) for k,v in T.items()}
NAMES={"en":"English","es":"Español","pt":"Português","fr":"Français","de":"Deutsch","it":"Italiano","ru":"Русский","kk":"Қазақша","tr":"Türkçe","ar":"العربية","hi":"हिन्दी","zh":"中文","ja":"日本語","ko":"한국어","id":"Bahasa Indonesia","vi":"Tiếng Việt","pl":"Polski","uk":"Українська"}
src='/** Interface translations (studio). Speech itself works in every ElevenLabs language. */\n'
src+='export const UI_LANGS: { code: string; native: string }[] = '+json.dumps([{"code":k,"native":NAMES[k]} for k in T],ensure_ascii=False)+';\n\n'
src+='const DICT: Record<string, Record<string, string>> = '+json.dumps(out,ensure_ascii=False,indent=0)+';\n\n'
src+='''export type Key = keyof typeof DICT["en"];
export function translate(lang: string, key: Key, vars?: Record<string, string | number>) {
  let s = (DICT[lang] && DICT[lang][key]) || DICT.en[key] || String(key);
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replace(`{${k}}`, String(v));
  return s;
}
export const isUiLang = (c?: string | null) => !!c && c in DICT;
'''
open('lib/i18n.ts','w').write(src)
print("ok", len(KEYS), "keys", len(T), "langs")
